// Pilih file Target Control dari ?sheet=okt|nov (default okt). Tambah bulan baru: tambah baris di SHEETS.
const SHEETS = {"okt": {"id": "1UoznzWqXZtCuSJZEbB7QKxombEumuKK80yCO1YZGGAQ", "nama": "OKTOBER 2026"}, "nov": {"id": "1wnfe5MmUnVKwdk4OLdGJOt8sHyRlCJlELEpvkK7DBBM", "nama": "NOV"}};
const q = ($input.first().json.query || {});
let s = String(q.sheet || q.bulan || 'okt').toLowerCase().slice(0, 3);
if (!SHEETS[s]) s = 'okt';
return [{ json: { sheet: s, docId: SHEETS[s].id, nama: SHEETS[s].nama } }];

// Susun data Monitoring Omzet Outlet (versi Oktober+): TARGET dari sheet "Target Control" (?sheet=okt|nov),
// REALISASI per outlet dari tab BulanBerlangsung di 7 sheet "Penutupan Kasir <outlet>".
// Input node: Pilih Sheet, Baca Periode (MASTER TARGET A1:B3), Baca Target Unit (MASTER TARGET B33:D58),
//   Baca Minggu 1..4 (MINGGUAN UNIT, hanya kolom TARGET untuk bobot minggu), Baca Kasir <Outlet> ×7 (BulanBerlangsung A1:G100).
// Kolom kasir dibaca PER POSISI (judul kolom beda-beda antar file): A Tanggal · D TOTAL KASPIN · E Tunai · F QRIS/Non-Tunai · G Ojol.
// ASUMSI (menunggu konfirmasi Nana):
//   1) omzet harian = E + F + G (Tunai + QRIS + Ojol, TANPA ongkir), dihitung ulang per baris; kolom D tidak dipercaya
//      (dulu rumus D Barombong 11 & 15 Okt salah, sudah diperbaiki Nana). Baris yang D-nya ≠ E+F+G tetap dicatat.
//   2) Sudiang = GOA RIA di MASTER TARGET.   3) Ojol 0 sepanjang bulan (Limbung/Tamalate) dibiarkan apa adanya.
// Minggu: M1 tgl 1–7, M2 8–14, M3 15–21, M4 22–akhir bulan (sesuai tab HARIAN TOTAL).
// Respon: {ok, generated_at, sumber, sheet, sumber_realisasi:'PENUTUPAN KASIR', bulan, periode, minggu, minggu_berjalan:{minggu,sampai_tgl,hari,hari_total}|null,
//   tgl_terakhir, bobot_minggu:[4], outlet:[{nama, target_bulanan, target_per_minggu:[4], realisasi_per_minggu:[4 angka|null], hari_terisi:[4], tgl_terakhir, file}],
//   kolom_d_beda:[{outlet,tanggal,d,efg}], gagal:[...], catatan:[...]}
// Aturan: minggu tanpa satu pun hari beromzet = null (belum diisi), BUKAN nol. Angka tidak pernah dikarang.
const KASIR = [   // node → nama UNIT di MASTER TARGET
  { node: 'Baca Kasir Sungai Poso', unit: 'SUNGAI POSO', file: 'Penutupan Kasir Sungai Poso' },
  { node: 'Baca Kasir Gowa', unit: 'GOWA', file: 'Penutupan Kasir Gowa' },
  { node: 'Baca Kasir Sudiang', unit: 'GOA RIA', file: 'Penutupan Kasir Sudiang' },
  { node: 'Baca Kasir Barombong', unit: 'BAROMBONG', file: 'Penutupan Kasir Barombong' },
  { node: 'Baca Kasir Limbung', unit: 'LIMBUNG', file: 'Penutupan Kasir Limbung' },
  { node: 'Baca Kasir Pare-Pare', unit: 'PARE-PARE', file: 'Penutupan Kasir Pare-Pare' },
  { node: 'Baca Kasir Tamalate', unit: 'TAMALATE', file: 'Penutupan Kasir Tamalate' }];
const MINGGU_AWAL = [1, 8, 15, 22];             // tgl awal M1..M4; M4 sampai akhir bulan
const BOBOT_DEFAULT = [0.27, 0.27, 0.23, 0.23];   // cadangan bila target mingguan tidak terbaca
const BULAN = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const BLN = { JAN: 1, FEB: 2, MAR: 3, APR: 4, MEI: 5, MAY: 5, JUN: 6, JUL: 7, AGU: 8, AGT: 8, AUG: 8, SEP: 9, OKT: 10, OCT: 10, NOV: 11, NOP: 11, DES: 12, DEC: 12 };
const t = v => (v == null ? '' : String(v).trim());
const key = v => t(v).toUpperCase().replace(/\s+/g, ' ');
// angka dari 58050000 / "Rp58.050.000" / "58,050,000" / "" → number | null
const num = v => {
  if (typeof v === 'number') return isFinite(v) ? v : null;
  let s = t(v).replace(/rp/i, '').replace(/\s/g, '');
  if (!s || s === '-') return null;
  if (/^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');   // format Indonesia
  else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) ? n : null;
};
// tanggal: serial Sheets (angka) / "2026-10-01" / "01/10/2026" (dd/mm, locale Indonesia) / "1-10-2026" / "1 Oktober 2026" → Date UTC | null
const toDate = v => {
  if (typeof v === 'number') return v > 20000 && v < 80000 ? new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 864e5) : null;
  const s = t(v); let m;
  if ((m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s))) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  if ((m = /^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/.exec(s))) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  if ((m = /^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?\s+(\d{4})/.exec(s)) && BLN[m[2].toUpperCase()]) return new Date(Date.UTC(+m[3], BLN[m[2].toUpperCase()] - 1, +m[1]));
  if (/^\d+(\.\d+)?$/.test(s)) return toDate(Number(s));
  return null;
};
// Nama node bisa berakhiran angka di n8n (mis. "Baca Minggu 11" saat ditempel) → coba nama persis lalu +1..+5. null = tidak jalan.
const baca = node => {
  for (const n of [node, 1, 2, 3, 4, 5].map((x, i) => i ? node + x : node)) {
    try { return $(n).all().map(it => it.json); } catch (e) { /* coba nama berikutnya */ }
  }
  return null;
};
const gagal = [], catatan = [];
const rowsOf = node => { const r = baca(node); if (r === null || r.some(x => x && x.error)) { gagal.push(node); return []; } return r.filter(Boolean); };
const vals = r => Object.keys(r).filter(k => k !== 'row_number').map(k => r[k]);   // urutan kolom rentang (A, B, C, …)
const rpID = n => 'Rp' + Math.round(n).toLocaleString('id-ID');

// ---- periode (MASTER TARGET baris "PERIODE:") ----
let periodeDate = null;
for (const r of rowsOf('Baca Periode')) {
  const v = vals(r);
  if (key(v[0]).startsWith('PERIODE')) periodeDate = toDate(v[1]);
  Object.keys(r).forEach((k, i, ks) => { if (!periodeDate && key(k).startsWith('PERIODE') && ks[i + 1]) periodeDate = toDate(ks[i + 1]); });
}
if (!periodeDate) { const n = new Date(); periodeDate = new Date(Date.UTC(n.getFullYear(), n.getMonth(), 1)); catatan.push('PERIODE di MASTER TARGET tidak terbaca, memakai bulan berjalan'); }
const TH = periodeDate.getUTCFullYear(), BL = periodeDate.getUTCMonth();
const bulan = TH + '-' + String(BL + 1).padStart(2, '0');
const periode = BULAN[BL] + ' ' + TH;
const hariBulan = new Date(Date.UTC(TH, BL + 1, 0)).getUTCDate();
const mingguDari = tgl => tgl >= 22 ? 3 : tgl >= 15 ? 2 : tgl >= 8 ? 1 : 0;
const akhirMinggu = w => w === 3 ? hariBulan : MINGGU_AWAL[w + 1] - 1;

// ---- target bulanan per unit (MASTER TARGET) + target mingguan (MINGGUAN UNIT, untuk bobot) ----
const outlet = [], idx = {};
const ambil = nama => { const k = key(nama); if (!idx[k]) { idx[k] = { nama: t(nama), target_bulanan: null, target_per_minggu: [null, null, null, null], realisasi_per_minggu: [null, null, null, null], hari_terisi: [0, 0, 0, 0], tgl_terakhir: null, file: null }; outlet.push(idx[k]); } return idx[k]; };
for (const r of rowsOf('Baca Target Unit')) {
  const nama = t(r['APA?'] ?? vals(r)[0]);
  if (!nama) continue;
  ambil(nama).target_bulanan = num(r['BERAPA RP'] ?? vals(r)[2]);
}
for (let w = 0; w < 4; w++) {
  for (const r of rowsOf('Baca Minggu ' + (w + 1))) {
    const nama = t(r['UNIT BISNIS'] ?? vals(r)[0]);
    if (!nama || !idx[key(nama)]) continue;   // hanya unit yang ada di MASTER TARGET
    idx[key(nama)].target_per_minggu[w] = num(r['TARGET'] ?? vals(r)[1]);
  }
}

// ---- realisasi: Penutupan Kasir tiap outlet ----
const kolomDBeda = [], ojolNol = [];
let tglTerakhir = 0;
for (const k of KASIR) {
  const raw = baca(k.node);
  if (raw === null || raw.some(x => x && x.error)) { gagal.push(k.node); continue; }
  const o = idx[key(k.unit)];
  if (!o) { catatan.push('Unit ' + k.unit + ' (' + k.file + ') tidak ada di MASTER TARGET, tidak dihitung'); continue; }
  o.file = k.file;
  const perTgl = {}; let ojol = 0, adaBaris = 0, tanpaTgl = 0, luar = 0;
  for (const r of raw) {
    const v = vals(r);
    const tunai = num(v[4]) || 0, qris = num(v[5]) || 0, oj = num(v[6]) || 0, efg = tunai + qris + oj;
    const d = toDate(v[0]);
    if (!d) { if (efg) tanpaTgl++; continue; }
    if (d.getUTCFullYear() !== TH || d.getUTCMonth() !== BL) { if (efg) luar++; continue; }
    if (!efg) continue;                                    // baris tanggal yang belum diisi
    const tgl = d.getUTCDate(); adaBaris++; ojol += oj;
    if (perTgl[tgl] != null) catatan.push(o.nama + ': tanggal ' + tgl + ' muncul lebih dari sekali, omzetnya dijumlah');
    perTgl[tgl] = (perTgl[tgl] || 0) + efg;
    const D = num(v[3]);
    if (D != null && Math.abs(D - efg) > 1) kolomDBeda.push({ outlet: o.nama, tanggal: bulan + '-' + String(tgl).padStart(2, '0'), d: D, efg });
  }
  if (tanpaTgl) catatan.push(o.nama + ': ' + tanpaTgl + ' baris berisi angka tapi tanpa tanggal, tidak dihitung');
  if (luar) catatan.push(o.nama + ': ' + luar + ' baris bertanggal di luar ' + periode + ', tidak dihitung');
  for (const [tg, val] of Object.entries(perTgl)) {
    const w = mingguDari(+tg);
    o.realisasi_per_minggu[w] = (o.realisasi_per_minggu[w] || 0) + val;
    o.hari_terisi[w]++;
    o.tgl_terakhir = Math.max(o.tgl_terakhir || 0, +tg);
  }
  tglTerakhir = Math.max(tglTerakhir, o.tgl_terakhir || 0);
  if (adaBaris && !ojol) ojolNol.push(o.nama);
  if (!adaBaris) catatan.push(o.nama + ': belum ada omzet ' + periode + ' di ' + k.file);
}
catatan.push('Asumsi: omzet harian = Tunai + QRIS + Ojol (kolom E+F+G, tanpa ongkir), dihitung ulang per baris; kolom D (TOTAL KASPIN) tidak dipakai. Sudiang = GOA RIA. Mohon konfirmasi.');
if (kolomDBeda.length) catatan.push('Rumus kolom D beda dengan E+F+G (dipakai E+F+G): ' + kolomDBeda.map(x => x.outlet + ' ' + +x.tanggal.slice(8) + '/' + (BL + 1) + ' (D ' + rpID(x.d) + ' vs E+F+G ' + rpID(x.efg) + ')').join('; '));
if (ojolNol.length) catatan.push('Ojol 0 sepanjang bulan: ' + ojolNol.join(', ') + ' (dibiarkan apa adanya, asumsi)');

const hasil = outlet.filter(o => (o.target_bulanan || 0) > 0 || o.realisasi_per_minggu.some(v => v != null));
hasil.filter(o => !(o.target_bulanan > 0)).forEach(o => catatan.push('Target bulanan ' + o.nama + ' kosong di MASTER TARGET'));
hasil.filter(o => !o.file).forEach(o => catatan.push(o.nama + ' tidak punya sheet Penutupan Kasir di flow ini'));
hasil.filter(o => o.tgl_terakhir && o.tgl_terakhir < tglTerakhir).forEach(o => catatan.push(o.nama + ' baru terisi s/d tgl ' + o.tgl_terakhir + ' (outlet lain s/d tgl ' + tglTerakhir + ')'));

// ---- bobot minggu = total target minggu ÷ total target bulanan ----
const totBulan = hasil.reduce((s, o) => s + (o.target_bulanan || 0), 0);
let bobot = [0, 1, 2, 3].map(w => { const s = hasil.reduce((a, o) => a + (o.target_per_minggu[w] || 0), 0); return totBulan > 0 ? Math.round(s / totBulan * 10000) / 10000 : null; });
if (bobot.some(b => b == null || b <= 0)) { bobot = BOBOT_DEFAULT.slice(); catatan.push('Bobot minggu dari sheet tidak terbaca, memakai default 27/27/23/23%'); }

// ---- minggu pelaporan = minggu terakhir yang LENGKAP (tgl terakhir ber-omzet ≥ akhir minggu); minggu sesudahnya = berjalan ----
let minggu = 0, mingguBerjalan = null;
if (tglTerakhir) {
  const w = mingguDari(tglTerakhir);
  if (tglTerakhir >= akhirMinggu(w)) minggu = w + 1;
  else {
    minggu = w;   // 0 bila minggu 1 belum lengkap
    mingguBerjalan = { minggu: w + 1, sampai_tgl: tglTerakhir, hari: tglTerakhir - MINGGU_AWAL[w] + 1, hari_total: akhirMinggu(w) - MINGGU_AWAL[w] + 1 };
    if (!minggu) minggu = w + 1;   // belum ada minggu lengkap → tampilkan minggu berjalan
  }
} else catatan.push('Belum ada omzet ' + periode + ' di sheet Penutupan Kasir');

const pilih = (baca('Pilih Sheet') || [])[0] || {};
return [{ json: { ok: true, generated_at: DateTime.now().setZone('Asia/Makassar').toISO(), sumber: 'Target Control ' + (pilih.nama || '') + ' (target) · Penutupan Kasir 7 outlet (realisasi E+F+G)', sheet: pilih.sheet || null,
  sumber_realisasi: 'PENUTUPAN KASIR', realisasi_cakupan: 'Tunai + QRIS + Ojol (E+F+G), tanpa ongkir',
  bulan, periode, minggu, minggu_berjalan: mingguBerjalan, tgl_terakhir: tglTerakhir || null, bobot_minggu: bobot, outlet: hasil, kolom_d_beda: kolomDBeda, gagal, catatan } }];
